do $$
declare
  v_tank uuid;
  v_count integer;
  v_sum numeric;
  v_min integer;
  v_max integer;
  v_at1450 numeric;
  v_at_full numeric;
  v_nonmono integer;
begin
  select id into v_tank from public.tanks where code = 'T1';

  select count(*), sum(litres), min(dip_mm), max(dip_mm)
    into v_count, v_sum, v_min, v_max
  from public.tank_calibration where tank_id = v_tank and version = 1;

  if v_count <> 2070 then
    raise exception 'Tank 1 chart has % rows, expected 2070', v_count;
  end if;
  if v_min <> 1 or v_max <> 2070 then
    raise exception 'Tank 1 chart spans %-% mm, expected 1-2070', v_min, v_max;
  end if;
  if v_sum <> 11565608 then
    raise exception 'Tank 1 chart checksum is %, expected 11565608 — the data was altered in transit', v_sum;
  end if;

  select litres into v_at1450 from public.tank_calibration
   where tank_id = v_tank and version = 1 and dip_mm = 1450;
  select litres into v_at_full from public.tank_calibration
   where tank_id = v_tank and version = 1 and dip_mm = 2070;
  if v_at1450 <> 8455 then raise exception 'Tank 1 at 1450 mm is % L, expected 8455', v_at1450; end if;
  if v_at_full <> 12000 then raise exception 'Tank 1 at 2070 mm is % L, expected 12000', v_at_full; end if;

  select count(*) into v_nonmono from (
    select litres, lag(litres) over (order by dip_mm) as prev
    from public.tank_calibration where tank_id = v_tank and version = 1
  ) q where prev is not null and litres <= prev;
  if v_nonmono > 0 then
    raise exception 'Tank 1 chart is not strictly increasing at % points', v_nonmono;
  end if;

  raise notice 'Tank 1: 2070 certified rows loaded and verified';
end $$;
